def backfill_active_admissions(apps, schema_editor):
    Bed = apps.get_model("core", "Bed")
    InpatientAdmission = apps.get_model("core", "InpatientAdmission")
    occupied_beds = (
        Bed.objects.filter(patient__isnull=False)
        .select_related("patient", "patient__assigned_clinician")
        .order_by("created_at", "id")
    )
    admitted_patient_ids = set()

    for bed in occupied_beds:
        if bed.patient_id in admitted_patient_ids:
            bed.patient_id = None
            bed.status = "available"
            bed.save(update_fields=["patient", "status"])
            continue

        clinician = bed.patient.assigned_clinician
        InpatientAdmission.objects.create(
            organization_id=bed.organization_id,
            patient_id=bed.patient_id,
            bed_id=bed.pk,
            clinician_id=clinician.pk if clinician else None,
            department=(
                (clinician.department or clinician.specialty) if clinician else ""
            ),
            admitted_at=bed.created_at,
            room_rate_cents=bed.daily_rate_cents,
        )
        admitted_patient_ids.add(bed.patient_id)


